 * Find the AliasSpecification associated with the node, and tell
 * that AliasSpecification about the new node.
 */
private void visitAliasableNode(Node n, Node parent) {
  AliasSpecification aliasableNodes = aliasTypes.get(n.getType());
  aliasableNodes.visit(n, parent);
}

/**
 * Sanity check that our aliases are not already defined by
 * someone else.

 * @see #getRestrictedWithoutUndefined(JSType)
 */
private final Visitor<JSType> restrictUndefinedVisitor =
  new Visitor<JSType>() {
    public JSType caseEnumElementType(EnumElementType enumElementType) {
      JSType type = enumElementType.getPrimitiveType().visit(this);
      if (type != null && enumElementType.getPrimitiveType().equals(type)) {
        return enumElementType;
      } else {
        return type;
      }

